chart.expression:
SELECT CTACTB, DESCRCTA, CODCTACTB, CASE WHEN MES = 'MES01' THEN 'Jan' WHEN MES = 'MES02' THEN 'Fev' WHEN MES = 'MES03' THEN 'Mar' WHEN MES = 'MES04' THEN 'Abr' WHEN MES = 'MES05' THEN 'Mai' WHEN MES = 'MES06' THEN 'Jun' WHEN MES = 'MES07' THEN 'Jul' WHEN MES = 'MES08' THEN 'Ago' WHEN MES = 'MES09' THEN 'Set' WHEN MES = 'MES10' THEN 'Out' WHEN MES = 'MES11' THEN 'Nov' WHEN MES = 'MES12' THEN 'Dez' ELSE MES END AS MES, SALDO FROM (
SELECT CODCTACTB, CTACTB, DESCRCTA, SUM(VALOR) AS VALOR, SUM(MES01) AS MES01, SUM(MES02) AS MES02, SUM(MES03) AS MES03, SUM(MES04) AS MES04, SUM(MES05) AS MES05, SUM(MES06) AS MES06, SUM(MES07) AS MES07, SUM(MES08) AS MES08, SUM(MES09) AS MES09, SUM(MES10) AS MES10, SUM(MES11) AS MES11, SUM(MES12) AS MES12 FROM ( SELECT PLA.CODCTACTB, PLA.CTACTB, PLA.DESCRCTA, SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) As VALOR, LAN.REFERENCIA, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/01' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES01, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/02' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES02, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/03' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES03, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/04' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES04, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/05' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES05, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/06' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES06, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/07' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES07, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/08' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES08, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/09' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES09, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/10' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES10, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/11' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES11, CASE WHEN TO_CHAR(LAN.REFERENCIA, 'YYYY/MM') <= TO_CHAR(:DAT1, 'YYYY') || '/12' THEN SUM(LAN.VLRLANC * CASE WHEN LAN.TIPLANC = 'D' THEN 1 ELSE -1 END) ELSE 0 END AS MES12 FROM TCBLAN LAN, TCBPLA PLA, TCBEMP EMP, TSIEMP PAR WHERE ( LAN.DTMOV <= :DAT1) AND ( PLA.CTACTB >= '1') AND ( PLA.CTACTB < '3') AND ( LAN.NUMLOTE <> 9999) AND ( LAN.CODEMP IN :CODEMP) AND LAN.CODCTACTB = PLA.CODCTACTB AND PAR.CODEMP = LAN.CODEMP AND EMP.CODEMP = LAN.CODEMP AND NVL(LAN.VLRLANC,0) > 0 AND EMP.CODEMPPLACTA = PLA.CODEMP AND PLA.CTACTB = :CONTA GROUP BY PLA.CTACTB, PLA.CTACTB, PLA.DESCRCTA, LAN.REFERENCIA, PLA.CODCTACTB )CT5 GROUP BY CODCTACTB, CTACTB, DESCRCTA
)DADOS UNPIVOT ( SALDO FOR MES IN (MES01, MES02, MES03, MES04, MES05, MES06, MES07, MES08, MES09, MES10, MES11, MES12) ) WHERE SUBSTR(MES, -2, 2) <= TO_CHAR(:DAT1, 'MM') ORDER BY CTACTB, SUBSTR(MES, -2, 2)
